"use client";

import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Archive, BarChart3, BriefcaseBusiness, ChevronLeft, ChevronRight, Download, ExternalLink, FileImage, FolderKanban, GripVertical, LayoutDashboard, LoaderCircle, LogOut, Mail, Menu, Package, Pencil, Plus, RefreshCw, Save, Search, Settings, ShieldCheck, Sparkles, Trash2, UserRound, X } from "lucide-react";
import Image from "next/image";
import { useEffect, useState } from "react";

import { API_URL, AUTH_EXPIRED_EVENT, api } from "@/lib/api";
import { buildProfilePatch } from "@/lib/profile-payload";
import type { PageResult, ProfileRecord, ProjectMedia, ProjectRecord, ServiceFeature, ServicePackage, ServiceRecord } from "@/lib/types";
import { Button } from "./ui/button";

type AdminRow = Record<string, unknown> & { id?: string };
type Overview = { published_projects: number; draft_projects: number; active_services: number; new_requests: number; unread_messages: number; recent_requests: AdminRow[] };
type Section = { key: string; label: string; icon: React.ComponentType<{ size?: number }> };
const sections: Section[] = [
  { key: "overview", label: "Overview", icon: LayoutDashboard }, { key: "profile", label: "Profile", icon: UserRound },
  { key: "projects", label: "Projects", icon: FolderKanban }, { key: "project-media", label: "Project Media", icon: FileImage },
  { key: "skills", label: "Skills", icon: Sparkles }, { key: "services", label: "Services", icon: BriefcaseBusiness },
  { key: "packages", label: "Packages", icon: Package }, { key: "project-requests", label: "Requests", icon: Mail },
  { key: "contact-messages", label: "Contact Messages", icon: Mail }, { key: "experiences", label: "Experience", icon: BarChart3 },
  { key: "education", label: "Education", icon: BarChart3 }, { key: "activities", label: "Activities", icon: Sparkles },
  { key: "social-links", label: "Social Links", icon: ExternalLink }, { key: "site-settings", label: "Site Settings", icon: Settings },
  { key: "audit-logs", label: "Audit Logs", icon: ShieldCheck },
];

function Login({ onSuccess }: { onSuccess: () => void }) {
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  async function submit(form: FormData) {
    setBusy(true);
    try { await api("/auth/login", { method: "POST", body: JSON.stringify({ email: form.get("email"), password: form.get("password") }) }); onSuccess(); }
    catch { setError("Invalid credentials or the API is unavailable."); }
    finally { setBusy(false); }
  }
  return <main className="admin-login"><form action={submit} className="admin-login-card"><p className="eyebrow">Private system</p><h1>Portfolio administration</h1><p>Manage projects, services, packages, media, profile content, and client requests.</p><label className="field"><span>Email</span><input name="email" type="email" autoComplete="username" required /></label><label className="field"><span>Password</span><input name="password" type="password" minLength={12} autoComplete="current-password" required /></label><Button disabled={busy}>{busy && <LoaderCircle className="spin" size={16} />}{busy ? "Signing in…" : "Sign in"}</Button>{error && <p className="form-error" role="alert">{error}</p>}</form></main>;
}

export function AdminDashboard() {
  const client = useQueryClient();
  const [loggedIn, setLoggedIn] = useState<boolean | null>(null);
  const [active, setActive] = useState("overview");
  const [navOpen, setNavOpen] = useState(false);
  useEffect(() => { api("/auth/me").then(() => setLoggedIn(true)).catch(() => setLoggedIn(false)); }, []);
  useEffect(() => { const expired = () => { client.clear(); setLoggedIn(false); }; window.addEventListener(AUTH_EXPIRED_EVENT, expired); return () => window.removeEventListener(AUTH_EXPIRED_EVENT, expired); }, [client]);
  if (loggedIn === null) return <main className="admin-login"><LoaderCircle className="spin" /></main>;
  if (!loggedIn) return <Login onSuccess={() => setLoggedIn(true)} />;
  const section = sections.find((item) => item.key === active) || sections[0];
  return <main className="admin-shell">
    <aside className={`admin-sidebar ${navOpen ? "open" : ""}`}><div className="admin-brand"><span>A/</span>Control<button aria-label="Close navigation" onClick={() => setNavOpen(false)}><X /></button></div><nav>{sections.map((item) => { const Icon = item.icon; return <button className={active === item.key ? "active" : ""} onClick={() => { setActive(item.key); setNavOpen(false); }} key={item.key}><Icon size={17} />{item.label}</button>; })}</nav><Button variant="outline" onClick={async () => { await api("/auth/logout", { method: "POST" }); client.clear(); setLoggedIn(false); }}><LogOut size={16} />Sign out</Button></aside>
    <section className="admin-main"><header className="admin-topbar"><button className="admin-menu" onClick={() => setNavOpen(true)} aria-label="Open navigation"><Menu /></button><div><p className="eyebrow">Content management</p><h1>{section.label}</h1></div><Button variant="outline" size="sm" onClick={() => client.invalidateQueries()}><RefreshCw size={15} />Refresh</Button></header>
      {active === "overview" && <OverviewPanel />}{active === "profile" && <ProfileManager />}{(active === "projects" || active === "project-media") && <ProjectManager mediaFirst={active === "project-media"} />}{(active === "services" || active === "packages") && <ServiceManager packagesFirst={active === "packages"} />}{active === "project-requests" && <RequestManager />}{!["overview", "profile", "projects", "project-media", "services", "packages", "project-requests"].includes(active) && <GenericManager resource={active} />}
    </section>
  </main>;
}

function OverviewPanel() {
  const query = useQuery<Overview>({ queryKey: ["admin", "overview"], queryFn: () => api("/admin/overview") });
  if (query.isLoading) return <AdminLoading />;
  if (!query.data) return <AdminError retry={() => query.refetch()} />;
  const cards = [["Published projects", query.data.published_projects], ["Draft projects", query.data.draft_projects], ["Active services", query.data.active_services], ["New requests", query.data.new_requests], ["Unread messages", query.data.unread_messages]];
  return <div className="admin-stack"><div className="overview-grid">{cards.map(([label, value]) => <article key={String(label)}><span>{label}</span><strong>{value}</strong></article>)}</div><section className="admin-panel"><div className="panel-heading"><div><h2>Recent requests</h2><p>The newest package and custom-offer inquiries.</p></div></div>{query.data.recent_requests.length ? <div className="record-list">{query.data.recent_requests.map((item) => <div className="record-row" key={String(item.id)}><div><b>{String(item.project_title)}</b><span>{String(item.client_name)} · {String(item.reference)}</span></div><span className="status-badge">{String(item.status)}</span></div>)}</div> : <AdminEmpty title="No requests yet" />}</section></div>;
}

const emptyProject: Partial<ProjectRecord> = { slug: "", title_en: "", title_ar: "", summary_en: "", summary_ar: "", technologies: [], media: [], publication_status: "draft", ownership_type: "personal", is_featured: false };

function ProjectManager({ mediaFirst }: { mediaFirst: boolean }) {
  const queryClient = useQueryClient();
  const [search, setSearch] = useState("");
  const [editing, setEditing] = useState<Partial<ProjectRecord> | null>(null);
  const query = useQuery<PageResult<ProjectRecord>>({ queryKey: ["admin", "projects", search], queryFn: () => api(`/admin/projects?page_size=100&search=${encodeURIComponent(search)}`) });
  async function archive(id: string) { if (!confirm("Archive this project? It will disappear publicly but remain recoverable.")) return; await api(`/admin/projects/${id}`, { method: "DELETE" }); await query.refetch(); }
  if (editing) return <ProjectEditor initial={editing} mediaFirst={mediaFirst} onClose={() => setEditing(null)} onSaved={async (project) => { setEditing(project); await query.refetch(); queryClient.invalidateQueries({ queryKey: ["admin", "overview"] }); }} />;
  return <section className="admin-panel"><div className="panel-heading"><div><h2>{mediaFirst ? "Choose a project to manage media" : "Projects"}</h2><p>Only bilingual name, description, and one technology are required.</p></div>{!mediaFirst && <Button onClick={() => setEditing(emptyProject)}><Plus size={16} />New project</Button>}</div><AdminSearch value={search} onChange={setSearch} />{query.isLoading ? <AdminLoading /> : query.isError ? <AdminError retry={() => query.refetch()} /> : query.data?.items.length ? <div className="record-list">{query.data.items.map((item) => <div className="record-row" key={item.id}><div><b>{item.title_en}</b><span>{item.technologies.join(" · ") || "No technologies"}</span></div><span className="status-badge">{item.publication_status}</span><div className="row-actions"><button aria-label="Edit" onClick={() => setEditing(item)}><Pencil size={16} /></button><button aria-label="Archive" onClick={() => archive(item.id)}><Archive size={16} /></button></div></div>)}</div> : <AdminEmpty title="No projects" action={() => setEditing(emptyProject)} />}</section>;
}

function ProjectEditor({ initial, onClose, onSaved, mediaFirst }: { initial: Partial<ProjectRecord>; onClose: () => void; onSaved: (project: ProjectRecord) => void; mediaFirst: boolean }) {
  const [draft, setDraft] = useState(initial);
  const [skills, setSkills] = useState((initial.technologies || []).join(", "));
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const set = (key: keyof ProjectRecord, value: unknown) => setDraft((current) => ({ ...current, [key]: value }));
  async function save() {
    setBusy(true); setError("");
    const technologies = skills.split(",").map((item) => item.trim()).filter(Boolean);
    try {
      const payload = { ...draft, technologies, media: undefined, id: undefined, created_at: undefined, updated_at: undefined, deleted_at: undefined };
      const project = await api<ProjectRecord>(draft.id ? `/admin/projects/${draft.id}` : "/admin/projects", { method: draft.id ? "PATCH" : "POST", body: JSON.stringify(payload) });
      onSaved(project);
    } catch { setError("Save failed. Check the required bilingual fields, slug, and technologies."); }
    finally { setBusy(false); }
  }
  const textArea = (key: keyof ProjectRecord, label: string, required = false) => <label className="field"><span>{label}{required && " *"}</span><textarea rows={key.toString().includes("summary") ? 4 : 3} value={String(draft[key] || "")} onChange={(event) => set(key, event.target.value)} required={required} /></label>;
  useUnsavedWarning(JSON.stringify(draft) !== JSON.stringify(initial) || skills !== (initial.technologies || []).join(", "));
  return <div className="admin-stack"><div className="editor-heading"><button onClick={onClose}><ChevronLeft />Back</button><div><h2>{draft.id ? "Edit project" : "Create project"}</h2><p>Optional sections remain hidden from visitors when empty.</p></div><div className="row-actions">{draft.publication_status === "published" && draft.slug && <a href={`/en/projects/${draft.slug}`} target="_blank" rel="noreferrer"><ExternalLink size={16} />Preview</a>}<Button onClick={save} disabled={busy}><Save size={16} />{busy ? "Saving…" : "Save project"}</Button></div></div>{error && <p className="form-error">{error}</p>}
    {!mediaFirst && <section className="admin-panel editor-form"><h3>Required information</h3><div className="admin-form-grid"><AdminField label="English name *" value={draft.title_en} onChange={(value) => set("title_en", value)} /><AdminField label="Arabic name *" value={draft.title_ar} onChange={(value) => set("title_ar", value)} dir="rtl" /><AdminField label="Slug *" value={draft.slug} onChange={(value) => set("slug", value.toLowerCase().replace(/[^a-z0-9-]+/g, "-"))} /><AdminField label="Skills / technologies *" value={skills} onChange={setSkills} hint="Comma-separated" /></div><div className="admin-form-grid">{textArea("summary_en", "English description", true)}{textArea("summary_ar", "Arabic description", true)}</div><h3>Presentation</h3><div className="admin-form-grid">{textArea("short_description_en", "English short description")}{textArea("short_description_ar", "Arabic short description")}<AdminField label="Category" value={draft.category} onChange={(value) => set("category", value)} /><AdminField label="Status (English)" value={draft.status_en} onChange={(value) => set("status_en", value)} /><AdminField label="Status (Arabic)" value={draft.status_ar} onChange={(value) => set("status_ar", value)} dir="rtl" /><label className="field"><span>Ownership</span><select value={draft.ownership_type || "personal"} onChange={(event) => set("ownership_type", event.target.value)}><option value="personal">Personal</option><option value="client">Client project</option><option value="university">University project</option><option value="team">Team project</option></select></label><label className="field"><span>Publication</span><select value={draft.publication_status || "draft"} onChange={(event) => set("publication_status", event.target.value)}><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></select></label><label className="checkbox"><input type="checkbox" checked={Boolean(draft.is_featured)} onChange={(event) => set("is_featured", event.target.checked)} />Featured</label></div><h3>Optional links and facts</h3><div className="admin-form-grid"><AdminField label="Live website URL" value={draft.live_url} onChange={(value) => set("live_url", value || null)} type="url" /><AdminField label="Demo URL" value={draft.demo_url} onChange={(value) => set("demo_url", value || null)} type="url" /><AdminField label="GitHub URL" value={draft.github_url} onChange={(value) => set("github_url", value || null)} type="url" /><AdminField label="Project date" value={draft.project_date} onChange={(value) => set("project_date", value || null)} type="date" /><AdminField label="Client name" value={draft.client_name} onChange={(value) => set("client_name", value || null)} /><AdminField label="Role (English)" value={draft.role_en} onChange={(value) => set("role_en", value || null)} /><AdminField label="Role (Arabic)" value={draft.role_ar} onChange={(value) => set("role_ar", value || null)} dir="rtl" /><AdminField label="Duration (English)" value={draft.development_duration_en} onChange={(value) => set("development_duration_en", value || null)} /><AdminField label="Duration (Arabic)" value={draft.development_duration_ar} onChange={(value) => set("development_duration_ar", value || null)} dir="rtl" /></div><h3>Case study sections</h3><div className="admin-form-grid">{textArea("problem_en", "Problem (English)")}{textArea("problem_ar", "Problem (Arabic)")}{textArea("solution_en", "Solution (English)")}{textArea("solution_ar", "Solution (Arabic)")}<ListField label="Features (English)" value={draft.features_en} onChange={(value) => set("features_en", value)} /><ListField label="Features (Arabic)" value={draft.features_ar} onChange={(value) => set("features_ar", value)} dir="rtl" />{textArea("architecture_en", "Architecture (English)")}{textArea("architecture_ar", "Architecture (Arabic)")}{textArea("challenges_en", "Challenges (English)")}{textArea("challenges_ar", "Challenges (Arabic)")}{textArea("implemented_solutions_en", "Implemented solutions (English)")}{textArea("implemented_solutions_ar", "Implemented solutions (Arabic)")}{textArea("results_en", "Results (English)")}{textArea("results_ar", "Results (Arabic)")}</div></section>}
    {draft.id ? <ProjectMediaManager project={draft as ProjectRecord} onChange={(media, cover) => { const updated = { ...draft, media, cover_url: cover === undefined ? draft.cover_url : cover }; setDraft(updated); onSaved(updated as ProjectRecord); }} /> : <section className="admin-panel admin-empty"><FileImage /><h3>Save the project before adding media</h3></section>}
  </div>;
}

function uploadWithProgress<T = ProjectMedia>(path: string, files: File[], onProgress: (value: number) => void) {
  return Promise.all(files.map((file, index) => new Promise<T>((resolve, reject) => {
    const xhr = new XMLHttpRequest(); const body = new FormData(); body.append("file", file);
    xhr.open("POST", `${API_URL}${path}`); xhr.withCredentials = true;
    xhr.upload.onprogress = (event) => event.lengthComputable && onProgress(Math.round(((index + event.loaded / event.total) / files.length) * 100));
    xhr.onload = () => xhr.status >= 200 && xhr.status < 300 ? resolve(JSON.parse(xhr.responseText) as T) : reject(new Error("Upload failed")); xhr.onerror = () => reject(new Error("Upload failed")); xhr.send(body);
  })));
}

function ProjectMediaManager({ project, onChange }: { project: ProjectRecord; onChange: (media: ProjectMedia[], cover?: string | null) => void }) {
  const [media, setMedia] = useState(project.media || []);
  const [previews, setPreviews] = useState<Array<{ file: File; url: string }>>([]);
  const [progress, setProgress] = useState(0);
  const [externalUrl, setExternalUrl] = useState("");
  const [dragged, setDragged] = useState<string | null>(null);
  function choose(files: FileList | null) { previews.forEach((item) => URL.revokeObjectURL(item.url)); setPreviews(Array.from(files || []).map((file) => ({ file, url: URL.createObjectURL(file) }))); }
  async function upload() { const rows = await uploadWithProgress(`/admin/projects/${project.id}/media`, previews.map((item) => item.file), setProgress); const next = [...media, ...rows]; setMedia(next); onChange(next); previews.forEach((item) => URL.revokeObjectURL(item.url)); setPreviews([]); setProgress(0); }
  async function addExternal() { const row = await api<ProjectMedia>(`/admin/projects/${project.id}/media/external`, { method: "POST", body: JSON.stringify({ url: externalUrl }) }); const next = [...media, row]; setMedia(next); onChange(next); setExternalUrl(""); }
  async function cover(item: ProjectMedia) { await api(`/admin/projects/${project.id}/cover?media_id=${item.id}`, { method: "POST" }); const next = media.map((row) => ({ ...row, is_cover: row.id === item.id })); setMedia(next); onChange(next, item.secure_url); }
  async function remove(item: ProjectMedia) { if (!confirm("Delete this media item? The Cloudinary asset is removed only when unused elsewhere.")) return; await api(`/admin/project-media/${item.id}`, { method: "DELETE" }); const next = media.filter((row) => row.id !== item.id); setMedia(next); onChange(next, item.is_cover ? null : undefined); }
  async function edit(item: ProjectMedia) { const title_en = prompt("English title", item.title_en || ""); if (title_en === null) return; const title_ar = prompt("Arabic title", item.title_ar || ""); if (title_ar === null) return; const alt_text_en = prompt("English alt text", item.alt_text_en || ""); if (alt_text_en === null) return; const alt_text_ar = prompt("Arabic alt text", item.alt_text_ar || ""); if (alt_text_ar === null) return; const updated = await api<ProjectMedia>(`/admin/project-media/${item.id}`, { method: "PATCH", body: JSON.stringify({ title_en: title_en || null, title_ar: title_ar || null, alt_text_en: alt_text_en || null, alt_text_ar: alt_text_ar || null }) }); const next = media.map((row) => row.id === item.id ? updated : row); setMedia(next); onChange(next); }
  async function drop(over: string) { if (!dragged || dragged === over) return; const reordered = [...media]; const from = reordered.findIndex((item) => item.id === dragged); const to = reordered.findIndex((item) => item.id === over); const [item] = reordered.splice(from, 1); reordered.splice(to, 0, item); setMedia(reordered); setDragged(null); await api(`/admin/projects/${project.id}/media/reorder`, { method: "POST", body: JSON.stringify({ ids: reordered.map((row) => row.id) }) }); onChange(reordered); }
  return <section className="admin-panel"><div className="panel-heading"><div><h3>Project media</h3><p>Upload JPG, PNG, WebP, AVIF, MP4, or WebM. Drag saved items to reorder.</p></div></div><div className="media-upload-row"><label className="upload-field"><FileImage /><span>Select multiple images or videos</span><input type="file" multiple accept="image/jpeg,image/png,image/webp,image/avif,video/mp4,video/webm" onChange={(event) => choose(event.target.files)} /></label>{previews.length > 0 && <Button onClick={upload}>Upload {previews.length} file{previews.length > 1 && "s"}</Button>}</div>{progress > 0 && <div className="progress-track" aria-label="Upload progress"><span style={{ width: `${progress}%` }} /> <b>{progress}%</b></div>}{previews.length > 0 && <div className="preview-grid">{previews.map((item) => <div key={item.url}>{item.file.type.startsWith("image/") ? <Image src={item.url} alt="Upload preview" width={180} height={120} unoptimized /> : <video src={item.url} muted />}</div>)}</div>}
    <div className="external-media"><AdminField label="External YouTube or Vimeo URL" value={externalUrl} onChange={setExternalUrl} type="url" /><Button variant="outline" disabled={!externalUrl} onClick={addExternal}>Add video</Button></div>
    {media.length ? <div className="admin-media-grid">{media.map((item) => <article draggable onDragStart={() => setDragged(item.id)} onDragOver={(event) => event.preventDefault()} onDrop={() => drop(item.id)} key={item.id}><GripVertical className="drag-handle" />{item.thumbnail_url || item.media_type === "image" ? <Image src={item.thumbnail_url || item.secure_url} alt={item.alt_text_en || "Project media"} fill sizes="200px" /> : <div className="media-icon"><FileImage /></div>}<div><span>{item.media_type} · {item.source_type}</span>{item.is_cover && <b>Cover</b>}</div><div className="row-actions">{item.media_type === "image" && <button onClick={() => cover(item)}>Cover</button>}<button aria-label="Edit media metadata" onClick={() => edit(item)}><Pencil size={15} /></button><button aria-label="Delete media" onClick={() => remove(item)}><Trash2 size={15} /></button></div></article>)}</div> : <AdminEmpty title="No project media yet" />}
  </section>;
}

const emptyService: Partial<ServiceRecord> = { slug: "", title_en: "", title_ar: "", description_en: "", description_ar: "", related_skills: [], included_items_en: [], included_items_ar: [], excluded_items_en: [], excluded_items_ar: [], client_requirements_en: [], client_requirements_ar: [], packages: [], publication_status: "draft" } as Partial<ServiceRecord>;

function ServiceManager({ packagesFirst }: { packagesFirst: boolean }) {
  const [search, setSearch] = useState(""); const [editing, setEditing] = useState<Partial<ServiceRecord> | null>(null);
  const query = useQuery<PageResult<ServiceRecord>>({ queryKey: ["admin", "services", search], queryFn: () => api(`/admin/services?page_size=100&search=${encodeURIComponent(search)}`) });
  async function archive(id: string) { if (!confirm("Archive this service? Existing request snapshots remain unchanged.")) return; await api(`/admin/services/${id}`, { method: "DELETE" }); await query.refetch(); }
  if (editing) return <ServiceEditor initial={editing} packagesFirst={packagesFirst} onClose={() => setEditing(null)} onSaved={async (service) => { setEditing(service); await query.refetch(); }} />;
  return <section className="admin-panel"><div className="panel-heading"><div><h2>{packagesFirst ? "Choose a service to manage packages" : "Services"}</h2><p>Draft services stay private until their content and packages are ready.</p></div>{!packagesFirst && <Button onClick={() => setEditing(emptyService)}><Plus size={16} />New service</Button>}</div><AdminSearch value={search} onChange={setSearch} />{query.isLoading ? <AdminLoading /> : query.data?.items.length ? <div className="record-list">{query.data.items.map((item) => <div className="record-row" key={item.id}><div><b>{item.title_en}</b><span>{item.related_skills.join(" · ")}</span></div><span className="status-badge">{item.publication_status}</span><span className="status-badge">{item.packages.length}/3 packages</span><div className="row-actions"><button aria-label="Edit service" onClick={() => setEditing(item)}><Pencil size={16} /></button><button aria-label="Archive service" onClick={() => archive(item.id)}><Archive size={16} /></button></div></div>)}</div> : <AdminEmpty title="No services" action={() => setEditing(emptyService)} />}</section>;
}

function ServiceEditor({ initial, onClose, onSaved, packagesFirst }: { initial: Partial<ServiceRecord>; onClose: () => void; onSaved: (service: ServiceRecord) => void; packagesFirst: boolean }) {
  const [draft, setDraft] = useState(initial); const [skills, setSkills] = useState((initial.related_skills || []).join(", ")); const [error, setError] = useState("");
  const set = (key: keyof ServiceRecord, value: unknown) => setDraft((current) => ({ ...current, [key]: value }));
  const update = (service: ServiceRecord) => { setDraft(service); setSkills(service.related_skills.join(", ")); onSaved(service); };
  async function save() { try { const related_skills = skills.split(",").map((item) => item.trim()).filter(Boolean); const payload = { ...draft, related_skills, packages: undefined, comparison: undefined, faqs: undefined, related_projects: undefined, starting_price: undefined, shortest_delivery_days: undefined, id: undefined, created_at: undefined, updated_at: undefined, deleted_at: undefined }; const service = await api<ServiceRecord>(draft.id ? `/admin/services/${draft.id}` : "/admin/services", { method: draft.id ? "PATCH" : "POST", body: JSON.stringify(payload) }); update(service); setError(""); } catch { setError("Save failed. Name, description, slug, and at least one related skill are required."); } }
  useUnsavedWarning(JSON.stringify(draft) !== JSON.stringify(initial) || skills !== (initial.related_skills || []).join(", "));
  return <div className="admin-stack"><div className="editor-heading"><button onClick={onClose}><ChevronLeft />Back</button><div><h2>{draft.id ? "Edit service" : "Create service"}</h2><p>Configure commercial details only through the package forms.</p></div><div className="row-actions">{draft.publication_status === "published" && draft.slug && <a href={`/en/services/${draft.slug}`} target="_blank" rel="noreferrer"><ExternalLink size={16} />Preview</a>}<Button onClick={save}><Save size={16} />Save service</Button></div></div>{error && <p className="form-error">{error}</p>}{!packagesFirst && <section className="admin-panel editor-form"><h3>Service content</h3><div className="admin-form-grid"><AdminField label="English name *" value={draft.title_en} onChange={(value) => set("title_en", value)} /><AdminField label="Arabic name *" value={draft.title_ar} onChange={(value) => set("title_ar", value)} dir="rtl" /><AdminField label="Slug *" value={draft.slug} onChange={(value) => set("slug", value.toLowerCase().replace(/[^a-z0-9-]+/g, "-"))} /><AdminField label="Related skills *" value={skills} onChange={setSkills} hint="Comma-separated" /><AdminField label="Category" value={draft.category} onChange={(value) => set("category", value || null)} /><AdminField label="Icon name" value={draft.icon} onChange={(value) => set("icon", value)} /><AdminField label="Cover image URL" value={draft.cover_image_url} onChange={(value) => set("cover_image_url", value || null)} type="url" /><AdminField label="Introduction video URL" value={draft.introduction_video_url} onChange={(value) => set("introduction_video_url", value || null)} type="url" /><label className="field"><span>Publication</span><select value={String(draft.publication_status || "draft")} onChange={(event) => set("publication_status" as keyof ServiceRecord, event.target.value)}><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></select></label><label className="field"><span>Availability</span><select value={draft.availability_status || "available"} onChange={(event) => set("availability_status", event.target.value)}><option value="available">Available</option><option value="temporarily_unavailable">Temporarily unavailable</option></select></label></div><div className="admin-form-grid"><AdminArea label="English description *" value={draft.description_en} onChange={(value) => set("description_en", value)} /><AdminArea label="Arabic description *" value={draft.description_ar} onChange={(value) => set("description_ar", value)} dir="rtl" /><AdminArea label="English short description" value={draft.short_description_en} onChange={(value) => set("short_description_en", value || null)} /><AdminArea label="Arabic short description" value={draft.short_description_ar} onChange={(value) => set("short_description_ar", value || null)} dir="rtl" /><AdminArea label="Scope (English)" value={draft.scope_en} onChange={(value) => set("scope_en", value || null)} /><AdminArea label="Scope (Arabic)" value={draft.scope_ar} onChange={(value) => set("scope_ar", value || null)} dir="rtl" /></div><h3>General lists</h3><div className="admin-form-grid"><ListField label="Included items (English)" value={draft.included_items_en} onChange={(value) => set("included_items_en", value)} /><ListField label="Included items (Arabic)" value={draft.included_items_ar} onChange={(value) => set("included_items_ar", value)} dir="rtl" /><ListField label="Excluded items (English)" value={draft.excluded_items_en} onChange={(value) => set("excluded_items_en", value)} /><ListField label="Excluded items (Arabic)" value={draft.excluded_items_ar} onChange={(value) => set("excluded_items_ar", value)} dir="rtl" /><ListField label="Client requirements (English)" value={draft.client_requirements_en} onChange={(value) => set("client_requirements_en", value)} /><ListField label="Client requirements (Arabic)" value={draft.client_requirements_ar} onChange={(value) => set("client_requirements_ar", value)} dir="rtl" /></div></section>}{draft.id ? <><ServiceExtras service={draft as ServiceRecord} onChange={update} /><PackageManager service={draft as ServiceRecord} onChange={update} /><FeatureManager service={draft as ServiceRecord} onChange={update} /></> : <section className="admin-panel"><AdminEmpty title="Save the service before configuring packages" /></section>}</div>;
}

function blankPackage(type: ServicePackage["package_type"], serviceId: string): Partial<ServicePackage> { return { service_id: serviceId, package_type: type, name_en: type[0].toUpperCase() + type.slice(1), name_ar: type === "basic" ? "أساسية" : type === "standard" ? "قياسية" : "مميزة", currency: "USD", included_deliverables_en: [], included_deliverables_ar: [], excluded_items_en: [], excluded_items_ar: [], client_requirements_en: [], client_requirements_ar: [], is_active: true, is_recommended: type === "standard", unlimited_revisions: false, display_order: type === "basic" ? 0 : type === "standard" ? 1 : 2 }; }
function ServiceExtras({ service, onChange }: { service: ServiceRecord; onChange: (service: ServiceRecord) => void }) {
  const projects = useQuery<PageResult<ProjectRecord>>({ queryKey: ["admin", "projects", "service-links"], queryFn: () => api("/admin/projects?page_size=100") });
  const [coverProgress, setCoverProgress] = useState(0);
  const [projectId, setProjectId] = useState("");
  const [faq, setFaq] = useState({ question_en: "", question_ar: "", answer_en: "", answer_ar: "" });
  async function uploadCover(file: File | undefined) { if (!file) return; const [saved] = await uploadWithProgress<ServiceRecord>(`/admin/services/${service.id}/cover`, [file], setCoverProgress); setCoverProgress(0); onChange(saved); }
  async function removeCover() { await api(`/admin/services/${service.id}/cover`, { method: "DELETE" }); onChange({ ...service, cover_image_url: null }); }
  async function addFaq() { const saved = await api<NonNullable<ServiceRecord["faqs"]>[number]>(`/admin/services/${service.id}/faqs`, { method: "POST", body: JSON.stringify(faq) }); onChange({ ...service, faqs: [...(service.faqs || []), saved] }); setFaq({ question_en: "", question_ar: "", answer_en: "", answer_ar: "" }); }
  async function editFaq(item: NonNullable<ServiceRecord["faqs"]>[number]) { const question_en = prompt("Question (English)", item.question_en); if (question_en === null) return; const question_ar = prompt("Question (Arabic)", item.question_ar); if (question_ar === null) return; const answer_en = prompt("Answer (English)", item.answer_en); if (answer_en === null) return; const answer_ar = prompt("Answer (Arabic)", item.answer_ar); if (answer_ar === null) return; const saved = await api<NonNullable<ServiceRecord["faqs"]>[number]>(`/admin/service-faqs/${item.id}`, { method: "PATCH", body: JSON.stringify({ question_en, question_ar, answer_en, answer_ar }) }); onChange({ ...service, faqs: (service.faqs || []).map((row) => row.id === item.id ? saved : row) }); }
  async function removeFaq(id: string) { await api(`/admin/service-faqs/${id}`, { method: "DELETE" }); onChange({ ...service, faqs: (service.faqs || []).filter((item) => item.id !== id) }); }
  async function linkProject() { if (!projectId) return; const saved = await api<{ project: ProjectRecord }>(`/admin/services/${service.id}/related-projects`, { method: "POST", body: JSON.stringify({ project_id: projectId }) }); onChange({ ...service, related_projects: [...(service.related_projects || []), saved.project] }); setProjectId(""); }
  async function unlinkProject(id: string) { await api(`/admin/services/${service.id}/related-projects/${id}`, { method: "DELETE" }); onChange({ ...service, related_projects: (service.related_projects || []).filter((item) => item.id !== id) }); }
  const linked = new Set((service.related_projects || []).map((item) => item.id));
  return <section className="admin-panel editor-form"><div className="panel-heading"><div><h3>Service media and related content</h3><p>Upload a verified cover, curate FAQs, and connect published case studies.</p></div></div><div className="media-upload-row"><label className="upload-field"><FileImage /><span>{service.cover_image_url ? "Replace service cover" : "Upload service cover"}</span><input type="file" accept="image/jpeg,image/png,image/webp,image/avif" onChange={(event) => uploadCover(event.target.files?.[0])} /></label>{service.cover_image_url && <Button variant="outline" onClick={removeCover}><Trash2 size={15} />Remove cover</Button>}</div>{coverProgress > 0 && <div className="progress-track"><span style={{ width: `${coverProgress}%` }} /><b>{coverProgress}%</b></div>}<h3>Frequently asked questions</h3>{service.faqs?.length ? <div className="record-list">{service.faqs.map((item) => <div className="record-row" key={item.id}><div><b>{item.question_en}</b><span>{item.question_ar}</span></div><div className="row-actions"><button aria-label="Edit FAQ" onClick={() => editFaq(item)}><Pencil size={15} /></button><button aria-label="Delete FAQ" onClick={() => removeFaq(item.id)}><Trash2 size={15} /></button></div></div>)}</div> : null}<div className="admin-form-grid"><AdminField label="Question (English)" value={faq.question_en} onChange={(value) => setFaq((row) => ({ ...row, question_en: value }))} /><AdminField label="Question (Arabic)" value={faq.question_ar} onChange={(value) => setFaq((row) => ({ ...row, question_ar: value }))} dir="rtl" /><AdminArea label="Answer (English)" value={faq.answer_en} onChange={(value) => setFaq((row) => ({ ...row, answer_en: value }))} /><AdminArea label="Answer (Arabic)" value={faq.answer_ar} onChange={(value) => setFaq((row) => ({ ...row, answer_ar: value }))} dir="rtl" /></div><Button variant="outline" disabled={!Object.values(faq).every(Boolean)} onClick={addFaq}><Plus size={15} />Add FAQ</Button><h3>Related projects</h3>{service.related_projects?.length ? <div className="record-list">{service.related_projects.map((item) => <div className="record-row" key={item.id}><div><b>{item.title_en}</b><span>{item.title_ar}</span></div><button aria-label="Unlink project" onClick={() => unlinkProject(item.id)}><X size={15} /></button></div>)}</div> : null}<div className="external-media"><label className="field"><span>Project</span><select value={projectId} onChange={(event) => setProjectId(event.target.value)}><option value="">Choose a project</option>{projects.data?.items.filter((item) => !linked.has(item.id)).map((item) => <option value={item.id} key={item.id}>{item.title_en}</option>)}</select></label><Button variant="outline" disabled={!projectId} onClick={linkProject}>Link project</Button></div></section>;
}
function PackageManager({ service, onChange }: { service: ServiceRecord; onChange: (service: ServiceRecord) => void }) {
  const [selected, setSelected] = useState<ServicePackage["package_type"]>("basic");
  const current = service.packages.find((item) => item.package_type === selected) || blankPackage(selected, service.id);
  const [draft, setDraft] = useState<Partial<ServicePackage>>(current);
  useEffect(() => setDraft(service.packages.find((item) => item.package_type === selected) || blankPackage(selected, service.id)), [selected, service]);
  const set = (key: keyof ServicePackage, value: unknown) => setDraft((item) => ({ ...item, [key]: value }));
  async function save() { const payload = { ...draft, id: undefined, service_id: undefined, created_at: undefined, updated_at: undefined, deleted_at: undefined }; const saved = await api<ServicePackage>(draft.id ? `/admin/packages/${draft.id}` : `/admin/services/${service.id}/packages`, { method: draft.id ? "PATCH" : "POST", body: JSON.stringify(payload) }); const packages = [...service.packages.filter((item) => item.id !== saved.id && item.package_type !== saved.package_type), saved]; onChange({ ...service, packages }); }
  return <section className="admin-panel editor-form"><div className="panel-heading"><div><h3>Three-tier packages</h3><p>Package values stay optional until you create a tier; active tiers need the required commercial fields.</p></div></div><div className="package-tabs">{(["basic", "standard", "premium"] as const).map((type) => <button className={selected === type ? "active" : ""} onClick={() => setSelected(type)} key={type}>{type}<span>{service.packages.some((item) => item.package_type === type) ? "Configured" : "Not configured"}</span></button>)}</div><div className="admin-form-grid"><AdminField label="English package name *" value={draft.name_en} onChange={(value) => set("name_en", value)} /><AdminField label="Arabic package name *" value={draft.name_ar} onChange={(value) => set("name_ar", value)} dir="rtl" /><AdminField label="Price *" value={draft.price} onChange={(value) => set("price", value)} type="number" /><AdminField label="Currency *" value={draft.currency} onChange={(value) => set("currency", value.toUpperCase())} /><AdminField label="Delivery days *" value={draft.delivery_days} onChange={(value) => set("delivery_days", Number(value))} type="number" /><AdminField label="Revisions" value={draft.revisions} onChange={(value) => set("revisions", value === "" ? null : Number(value))} type="number" /></div><div className="admin-form-grid"><AdminArea label="Short description (English)" value={draft.short_description_en} onChange={(value) => set("short_description_en", value || null)} /><AdminArea label="Short description (Arabic)" value={draft.short_description_ar} onChange={(value) => set("short_description_ar", value || null)} dir="rtl" /><ListField label="Included deliverables (English) *" value={draft.included_deliverables_en} onChange={(value) => set("included_deliverables_en", value)} /><ListField label="Included deliverables (Arabic)" value={draft.included_deliverables_ar} onChange={(value) => set("included_deliverables_ar", value)} dir="rtl" /><ListField label="Excluded items (English)" value={draft.excluded_items_en} onChange={(value) => set("excluded_items_en", value)} /><ListField label="Excluded items (Arabic)" value={draft.excluded_items_ar} onChange={(value) => set("excluded_items_ar", value)} dir="rtl" /></div><div className="checkbox-row"><label className="checkbox"><input type="checkbox" checked={Boolean(draft.is_active)} onChange={(event) => set("is_active", event.target.checked)} />Active</label><label className="checkbox"><input type="checkbox" checked={Boolean(draft.is_recommended)} onChange={(event) => set("is_recommended", event.target.checked)} />Recommended</label><label className="checkbox"><input type="checkbox" checked={Boolean(draft.unlimited_revisions)} onChange={(event) => set("unlimited_revisions", event.target.checked)} />Unlimited revisions</label></div><Button onClick={save}><Save size={16} />{draft.id ? "Update package" : `Create ${selected} package`}</Button></section>;
}

function FeatureManager({ service, onChange }: { service: ServiceRecord; onChange: (service: ServiceRecord) => void }) {
  const features = service.comparison?.features || []; const activePackages = service.packages.filter((item) => item.is_active);
  const [nameEn, setNameEn] = useState(""); const [nameAr, setNameAr] = useState(""); const [type, setType] = useState<"boolean" | "number" | "text">("boolean"); const [values, setValues] = useState<Record<string, string | boolean>>({});
  async function create() { const payload = { name_en: nameEn, name_ar: nameAr, value_type: type, values: activePackages.map((item) => ({ package_id: item.id, value_boolean: type === "boolean" ? Boolean(values[item.id]) : null, value_number: type === "number" ? Number(values[item.id] || 0) : null, value_text_en: type === "text" ? String(values[item.id] || "") : null, value_text_ar: type === "text" ? String(values[item.id] || "") : null })) }; const feature = await api<ServiceFeature>(`/admin/services/${service.id}/features`, { method: "POST", body: JSON.stringify(payload) }); onChange({ ...service, comparison: { packages: service.packages, features: [...features, feature] } }); setNameEn(""); setNameAr(""); setValues({}); }
  async function remove(id: string) { await api(`/admin/service-features/${id}`, { method: "DELETE" }); onChange({ ...service, comparison: { packages: service.packages, features: features.filter((item) => item.id !== id) } }); }
  return <section className="admin-panel editor-form"><div className="panel-heading"><div><h3>Package feature matrix</h3><p>Features are service-specific and can use boolean, number, or text values.</p></div></div>{features.length > 0 && <div className="record-list">{features.map((item) => <div className="record-row" key={item.id}><div><b>{item.name_en}</b><span>{item.name_ar} · {item.value_type}</span></div><button onClick={() => remove(item.id)} aria-label="Delete feature"><Trash2 size={16} /></button></div>)}</div>}{activePackages.length ? <div className="feature-form"><div className="admin-form-grid"><AdminField label="Feature name (English)" value={nameEn} onChange={setNameEn} /><AdminField label="Feature name (Arabic)" value={nameAr} onChange={setNameAr} dir="rtl" /><label className="field"><span>Value type</span><select value={type} onChange={(event) => { setType(event.target.value as typeof type); setValues({}); }}><option value="boolean">Boolean</option><option value="number">Number</option><option value="text">Text</option></select></label></div><div className="feature-values">{activePackages.map((item) => <label className="field" key={item.id}><span>{item.name_en}</span>{type === "boolean" ? <input type="checkbox" checked={Boolean(values[item.id])} onChange={(event) => setValues((current) => ({ ...current, [item.id]: event.target.checked }))} /> : <input type={type === "number" ? "number" : "text"} value={String(values[item.id] || "")} onChange={(event) => setValues((current) => ({ ...current, [item.id]: event.target.value }))} />}</label>)}</div><Button disabled={!nameEn || !nameAr} onClick={create}><Plus size={16} />Add feature</Button></div> : <AdminEmpty title="Create active packages before adding comparison features" />}</section>;
}

function ProfileManager() {
  const query = useQuery<ProfileRecord & { id: string }>({ queryKey: ["admin", "profile"], queryFn: () => api("/admin/profile") });
  const [draft, setDraft] = useState<ProfileRecord>({}); const [photo, setPhoto] = useState<File | null>(null); const [preview, setPreview] = useState(""); const [notice, setNotice] = useState(""); const [error, setError] = useState(""); const [saving, setSaving] = useState(false);
  useEffect(() => { if (query.data) setDraft(query.data); }, [query.data]);
  const set = (key: string, value: string | null) => setDraft((item) => ({ ...item, [key]: value }));
  async function save() { const body = buildProfilePatch(draft, query.data || {}); const hasFields = Object.keys(body).length > 0; if (!hasFields && !photo) { setError(""); setNotice("No profile changes to save."); return; } setSaving(true); setError(""); setNotice(""); try { if (hasFields) await api("/admin/profile", { method: "PATCH", body: JSON.stringify(body) }); if (photo) { const uploadBody = new FormData(); uploadBody.append("file", photo); uploadBody.append("alt_text_en", String(draft.profile_image_alt_en || draft.name_en || "Profile portrait")); uploadBody.append("alt_text_ar", String(draft.profile_image_alt_ar || draft.name_ar || "الصورة الشخصية")); await api("/admin/profile/photo", { method: "POST", body: uploadBody }); if (preview) URL.revokeObjectURL(preview); setPreview(""); setPhoto(null); } setNotice(photo && hasFields ? "Profile and photo saved." : photo ? "Profile photo saved." : "Profile saved."); await query.refetch(); } catch (caught) { setError(caught instanceof Error ? caught.message : "Profile save failed."); } finally { setSaving(false); } }
  if (query.isLoading) return <AdminLoading />;
  return <div className="admin-stack"><section className="admin-panel editor-form"><div className="panel-heading"><div><h2>Profile and Hero</h2><p>Public profile content comes from these fields—nothing is hard-coded in the Hero.</p></div><Button onClick={save} disabled={saving}><Save size={16} />{saving ? "Saving…" : photo ? "Save profile & photo" : "Save profile"}</Button></div>{notice && <p className="form-success">{notice}</p>}{error && <p className="form-error" role="alert">{error}</p>}<div className="profile-admin-grid"><div className="profile-photo-admin">{preview || (typeof draft.profile_image_url === "string" && draft.profile_image_url) ? <Image src={preview || String(draft.profile_image_url)} alt="Profile preview" fill sizes="300px" unoptimized /> : <UserRound />}<label className="upload-field"><FileImage /><span>Choose profile photo</span><input type="file" accept="image/jpeg,image/png,image/webp,image/avif" onChange={(event) => { const file = event.target.files?.[0] || null; setPhoto(file); setError(""); setNotice(""); if (preview) URL.revokeObjectURL(preview); setPreview(file ? URL.createObjectURL(file) : ""); }} /></label>{photo && <p className="admin-hint">The selected photo will be uploaded when you save the profile.</p>}<AdminField label="Image position" value={draft.profile_image_position} onChange={(value) => set("profile_image_position", value)} hint="Example: 50% 35%" /><AdminField label="Alt text (English)" value={draft.profile_image_alt_en} onChange={(value) => set("profile_image_alt_en", value)} /><AdminField label="Alt text (Arabic)" value={draft.profile_image_alt_ar} onChange={(value) => set("profile_image_alt_ar", value)} dir="rtl" /></div><div className="admin-form-grid"><AdminField label="Full name (English)" value={draft.name_en} onChange={(value) => set("name_en", value)} /><AdminField label="Full name (Arabic)" value={draft.name_ar} onChange={(value) => set("name_ar", value)} dir="rtl" /><AdminField label="Professional title (English)" value={draft.title_en} onChange={(value) => set("title_en", value)} /><AdminField label="Professional title (Arabic)" value={draft.title_ar} onChange={(value) => set("title_ar", value)} dir="rtl" /><AdminField label="Hero heading (English)" value={draft.hero_heading_en} onChange={(value) => set("hero_heading_en", value)} /><AdminField label="Hero heading (Arabic)" value={draft.hero_heading_ar} onChange={(value) => set("hero_heading_ar", value)} dir="rtl" /><AdminArea label="Hero subheading (English)" value={draft.hero_subheading_en} onChange={(value) => set("hero_subheading_en", value)} /><AdminArea label="Hero subheading (Arabic)" value={draft.hero_subheading_ar} onChange={(value) => set("hero_subheading_ar", value)} dir="rtl" /><AdminArea label="About (English)" value={draft.about_en} onChange={(value) => set("about_en", value)} /><AdminArea label="About (Arabic)" value={draft.about_ar} onChange={(value) => set("about_ar", value)} dir="rtl" /><AdminField label="Email" value={draft.email} onChange={(value) => set("email", value)} type="email" /><AdminField label="Phone" value={draft.phone} onChange={(value) => set("phone", value)} /><AdminField label="WhatsApp" value={draft.whatsapp} onChange={(value) => set("whatsapp", value)} /><AdminField label="Telegram" value={draft.telegram} onChange={(value) => set("telegram", value)} /><AdminField label="GitHub URL" value={draft.github_url} onChange={(value) => set("github_url", value)} type="url" /><AdminField label="LinkedIn URL" value={draft.linkedin_url} onChange={(value) => set("linkedin_url", value)} type="url" /><AdminField label="Upwork URL" value={draft.upwork_url} onChange={(value) => set("upwork_url", value)} type="url" /><AdminField label="CV URL" value={draft.cv_url} onChange={(value) => set("cv_url", value)} type="url" /><AdminField label="Availability" value={draft.availability_status} onChange={(value) => set("availability_status", value)} /><AdminField label="Location (English)" value={draft.location_en} onChange={(value) => set("location_en", value)} /><AdminField label="Location (Arabic)" value={draft.location_ar} onChange={(value) => set("location_ar", value)} dir="rtl" /></div></div></section></div>;
}

function RequestManager() {
  const [search, setSearch] = useState(""); const [status, setStatus] = useState(""); const [selected, setSelected] = useState<AdminRow | null>(null); const [notes, setNotes] = useState("");
  const query = useQuery<PageResult<AdminRow>>({ queryKey: ["admin", "requests", search, status], queryFn: () => api(`/admin/project-requests?page_size=100&search=${encodeURIComponent(search)}&status=${status}`) });
  async function open(item: AdminRow) { const detail = await api<AdminRow>(`/admin/project-requests/${item.id}`); setSelected(detail); setNotes(String(detail.internal_notes || "")); }
  async function save() { if (!selected) return; const updated = await api<AdminRow>(`/admin/project-requests/${selected.id}`, { method: "PATCH", body: JSON.stringify({ status: selected.status, admin_notes: notes }) }); setSelected(updated); await query.refetch(); }
  return <section className="admin-panel"><div className="panel-heading"><div><h2>Client requests</h2><p>Package snapshots remain unchanged when services or prices are edited later.</p></div><Button asChild variant="outline"><a href={`${API_URL}/admin/project-requests/export.csv`}><Download size={16} />Export CSV</a></Button></div><div className="admin-filter-row"><AdminSearch value={search} onChange={setSearch} /><select value={status} onChange={(event) => setStatus(event.target.value)}><option value="">All statuses</option>{["new", "reviewing", "contacted", "in_discussion", "accepted", "rejected", "archived"].map((item) => <option key={item}>{item}</option>)}</select></div>{query.isLoading ? <AdminLoading /> : query.data?.items.length ? <div className="record-list">{query.data.items.map((item) => <button className="record-row request-row" onClick={() => open(item)} key={String(item.id)}><div><b>{String(item.project_title)}</b><span>{String(item.client_name)} · {String(item.reference)}</span></div><div><b>{String(item.package_name_snapshot || "Custom offer")}</b><span>{item.price_snapshot !== null && item.price_snapshot !== undefined ? `${String(item.currency_snapshot)} ${String(item.price_snapshot)}` : "No package price"}</span></div><span className="status-badge">{String(item.status)}</span><ChevronRight /></button>)}</div> : <AdminEmpty title="No requests found" />}{selected && <div className="admin-dialog" role="dialog" aria-modal="true"><section><div className="dialog-heading"><div><p className="eyebrow">{String(selected.reference)}</p><h2>{String(selected.project_title)}</h2></div><button onClick={() => setSelected(null)}><X /></button></div><div className="snapshot-grid">{[["Client", selected.client_name], ["Email", selected.email], ["Service snapshot", selected.service_name_snapshot], ["Package snapshot", selected.package_name_snapshot], ["Price snapshot", selected.price_snapshot !== null && selected.price_snapshot !== undefined ? `${String(selected.currency_snapshot)} ${String(selected.price_snapshot)}` : "Custom"], ["Delivery snapshot", selected.delivery_days_snapshot ? `${String(selected.delivery_days_snapshot)} days` : "—"]].map(([label, value]) => <div key={String(label)}><span>{String(label)}</span><b>{String(value || "—")}</b></div>)}</div><article className="request-description"><h3>Project description</h3><p>{String(selected.description)}</p></article><label className="field"><span>Status</span><select value={String(selected.status)} onChange={(event) => setSelected({ ...selected, status: event.target.value })}>{["new", "reviewing", "contacted", "in_discussion", "accepted", "rejected", "archived"].map((item) => <option key={item}>{item}</option>)}</select></label><label className="field"><span>Private internal notes</span><textarea rows={5} value={notes} onChange={(event) => setNotes(event.target.value)} /></label><div className="dialog-actions"><Button variant="outline" onClick={() => setSelected(null)}>Cancel</Button><Button onClick={save}>Save request</Button></div></section></div>}</section>;
}

function GenericManager({ resource }: { resource: string }) {
  const [editing, setEditing] = useState<AdminRow | null>(null); const [draft, setDraft] = useState("{}"); const [search, setSearch] = useState("");
  const query = useQuery<PageResult<AdminRow>>({ queryKey: ["admin", resource], queryFn: async () => { const value = await api<PageResult<AdminRow> | AdminRow[]>(`/admin/${resource}`); return Array.isArray(value) ? { items: value, page: 1, page_size: value.length, total: value.length, pages: 1 } : value; } });
  const rows = (query.data?.items || []).filter((item) => JSON.stringify(item).toLowerCase().includes(search.toLowerCase())); const readOnly = resource === "audit-logs";
  function edit(row: AdminRow | null) { const value = row || {}; setEditing(value); setDraft(JSON.stringify(Object.fromEntries(Object.entries(value).filter(([key]) => !["id", "created_at", "updated_at", "deleted_at"].includes(key))), null, 2)); }
  async function save() { if (!editing) return; await api(`/admin/${resource}${editing.id ? `/${editing.id}` : ""}`, { method: editing.id ? "PATCH" : "POST", body: draft }); setEditing(null); await query.refetch(); }
  return <section className="admin-panel"><div className="panel-heading"><div><h2>{resource.replaceAll("-", " ")}</h2><p>Advanced bilingual record management.</p></div>{!readOnly && !["contact-messages"].includes(resource) && <Button onClick={() => edit(null)}><Plus size={16} />New record</Button>}</div><AdminSearch value={search} onChange={setSearch} />{query.isLoading ? <AdminLoading /> : rows.length ? <div className="record-list">{rows.map((item, index) => <div className="record-row" key={String(item.id || index)}><div><b>{String(item.title_en || item.name || item.full_name || item.key || item.action || "Record")}</b><span>{String(item.description_en || item.email || item.entity_type || item.id || "")}</span></div><span className="status-badge">{String(item.publication_status || item.status || (item.is_active === false ? "inactive" : "active"))}</span>{!readOnly && <button onClick={() => edit(item)}><Pencil size={16} /></button>}</div>)}</div> : <AdminEmpty title="No records" />}{editing && <div className="admin-dialog"><section><div className="dialog-heading"><h2>{editing.id ? "Edit record" : "Create record"}</h2><button onClick={() => setEditing(null)}><X /></button></div><label className="field"><span>Content fields (JSON)</span><textarea className="json-editor" value={draft} onChange={(event) => setDraft(event.target.value)} /></label><p className="admin-hint">Use explicit _en and _ar fields. Never enter secrets here.</p><div className="dialog-actions"><Button variant="outline" onClick={() => setEditing(null)}>Cancel</Button><Button onClick={save}>Save</Button></div></section></div>}</section>;
}

function AdminField({ label, value, onChange, hint, dir, type = "text" }: { label: string; value: unknown; onChange: (value: string) => void; hint?: string; dir?: "rtl"; type?: string }) { return <label className="field"><span>{label}</span><input dir={dir} type={type} value={value === null || value === undefined ? "" : String(value)} onChange={(event) => onChange(event.target.value)} />{hint && <em>{hint}</em>}</label>; }
function AdminArea({ label, value, onChange, dir }: { label: string; value: unknown; onChange: (value: string) => void; dir?: "rtl" }) { return <label className="field"><span>{label}</span><textarea dir={dir} rows={4} value={value === null || value === undefined ? "" : String(value)} onChange={(event) => onChange(event.target.value)} /></label>; }
function ListField({ label, value, onChange, dir }: { label: string; value: unknown; onChange: (value: string[]) => void; dir?: "rtl" }) { const list = Array.isArray(value) ? value.map(String) : []; return <label className="field"><span>{label}</span><textarea dir={dir} rows={4} value={list.join("\n")} onChange={(event) => onChange(event.target.value.split("\n").map((item) => item.trim()).filter(Boolean))} /><em>One item per line</em></label>; }
function useUnsavedWarning(isDirty: boolean) { useEffect(() => { const warn = (event: BeforeUnloadEvent) => { if (!isDirty) return; event.preventDefault(); event.returnValue = ""; }; window.addEventListener("beforeunload", warn); return () => window.removeEventListener("beforeunload", warn); }, [isDirty]); }
function AdminSearch({ value, onChange }: { value: string; onChange: (value: string) => void }) { return <label className="admin-search"><Search size={17} /><span className="sr-only">Search</span><input placeholder="Search records" value={value} onChange={(event) => onChange(event.target.value)} /></label>; }
function AdminLoading() { return <div className="admin-empty"><LoaderCircle className="spin" /><p>Loading…</p></div>; }
function AdminError({ retry }: { retry: () => void }) { return <div className="admin-empty"><p>Could not load this section.</p><Button variant="outline" onClick={retry}>Try again</Button></div>; }
function AdminEmpty({ title, action }: { title: string; action?: () => void }) { return <div className="admin-empty"><FolderKanban /><h3>{title}</h3>{action && <Button onClick={action}><Plus size={16} />Create the first one</Button>}</div>; }
